CREATE TABLE IF NOT EXISTS alert_storm_policy(id SMALLINT PRIMARY KEY CHECK(id=1),enabled BOOLEAN NOT NULL DEFAULT TRUE,window_minutes INTEGER NOT NULL DEFAULT 5 CHECK(window_minutes BETWEEN 1 AND 60),event_threshold INTEGER NOT NULL DEFAULT 5 CHECK(event_threshold BETWEEN 2 AND 100),cooldown_minutes INTEGER NOT NULL DEFAULT 15 CHECK(cooldown_minutes BETWEEN 1 AND 240),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_by TEXT REFERENCES platform_users(id) ON DELETE SET NULL);
INSERT INTO alert_storm_policy(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS alert_storms(id TEXT PRIMARY KEY,host_id TEXT NOT NULL REFERENCES managed_hosts(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN ('active','ended')),event_count INTEGER NOT NULL,started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_event_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),summary_sent_at TIMESTAMPTZ,ended_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS alert_storms_status_idx ON alert_storms(status,last_event_at DESC);
